class Solution {
public:
    string findSpecialNodes(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        auto bfs = [&](int src) {
            vector<int> dist(n, -1); dist[src] = 0;
            queue<int> q; q.push(src);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) if (dist[v] < 0) { dist[v] = dist[u] + 1; q.push(v); }
            }
            return dist;
        };
        string ans(n, '0');
        int D = 0;
        vector<int> ecc(n);
        for (int i = 0; i < n; i++) {
            auto d = bfs(i);
            ecc[i] = *max_element(d.begin(), d.end());
            D = max(D, ecc[i]);
        }
        for (int i = 0; i < n; i++) if (ecc[i] == D) ans[i] = '1';
        return ans;
    }
};

