class Solution {
    public String findSpecialNodes(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] d0 = bfs(adj, n, 0);
        int u = 0; for (int i = 1; i < n; i++) if (d0[i] > d0[u]) u = i;
        int[] du = bfs(adj, n, u);
        int v = 0; for (int i = 1; i < n; i++) if (du[i] > du[v]) v = i;
        int[] dv = bfs(adj, n, v);
        int D = du[v];
        char[] ans = new char[n];
        for (int i = 0; i < n; i++) ans[i] = Math.max(du[i], dv[i]) == D ? '1' : '0';
        return new String(ans);
    }
    private int[] bfs(List<List<Integer>> adj, int n, int src) {
        int[] dist = new int[n]; Arrays.fill(dist, -1);
        Deque<Integer> q = new ArrayDeque<>(); q.add(src); dist[src] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) if (dist[v] < 0) { dist[v] = dist[u] + 1; q.add(v); }
        }
        return dist;
    }
}

